(21, 30, 128, 'Tugas 1 Analisis Teks / Analytical Exposition (Menulis Esai)', '1. Read the provided article/topic regarding current global issues (e.g., Digital Literacy, Climate Change, or Artificial Intelligence).\r\n2. Write an Analytical Exposition Text consisting of 250–350 words with the following structure:\r\n-Thesis: State your stance clearly.\r\n-Arguments: Provide at least 2 strong arguments supported by facts/evidence.\r\n-Reiteration: Restate your point of view.\r\n3. Format: Font Times New Roman 12, 1.5 spacing, saved in PDF or DOCX format.\r\n4. Submit before the deadline.', 'dokumen', NULL, 'essay', '2026-08-22 22:54:00', NULL, NULL, 17, NULL, 'aktif', 100, '2026-08-21 15:54:51', '2026-08-21 15:54:51', NULL),
(22, 30, 128, 'Video Presentasi Bahasa Inggris', 'Buat video presentasi berdurasi 3–5 menit, unggah ke YouTube sebagai Tidak Tercantum (Unlisted), kemudian kumpulkan tautannya.', 'audiovisual', 'video_url', 'essay', '2026-08-23 13:35:00', NULL, NULL, 17, NULL, 'aktif', 100, '2026-08-22 06:36:07', '2026-08-22 06:36:07', NULL),
(23, 30, 128, 'English Campaign Poster: Speak with Confidence', 'Create an original English poster with the theme “Speak English with Confidence.” Your poster must contain a clear title, a short motivational slogan, and at least three practical tips for improving English skills. Use the attached poster only as a reference and do not copy it exactly. Submit your work in JPG, JPEG, PNG, or PDF format with a maximum size of 20 MB.', 'visual', NULL, 'essay', '2026-08-22 17:02:00', 'tugas/eKRy2EG0FEs2pmPEtk04rvBYCfSjT7P3uM1Skk4O.png', NULL, 17, NULL, 'aktif', 100, '2026-08-22 07:05:36', '2026-08-22 07:05:36', NULL),
